// Feasible check: evaluate a verbatim transcription of port.ts's logic.
// NOTE: this runs a copy in the sandbox, NOT the on-disk port.ts, and is NOT
// a substitute for the required compiler (standalone-pilot-tsc).
const MIN_PORT = 1;
const MAX_PORT = 65535;
function port(value) {
  if (typeof value === "number") {
    if (!Number.isInteger(value) || value < MIN_PORT || value > MAX_PORT) {
      throw new TypeError(`port must be an integer between ${MIN_PORT} and ${MAX_PORT}`);
    }
    return value;
  }
  if (typeof value === "string") {
    if (!/^[0-9]+$/.test(value)) {
      throw new TypeError("port must be an ASCII decimal digit string");
    }
    const n = Number(value);
    if (n < MIN_PORT || n > MAX_PORT) {
      throw new TypeError(`port must be an integer between ${MIN_PORT} and ${MAX_PORT}`);
    }
    return n;
  }
  throw new TypeError("port must be an integer number or a decimal digit string");
}

const cases = [
  // [label, value, expected] where expected is "ok:<n>" or "throw"
  ["number 1", 1, "ok:1"],
  ["number 65535", 65535, "ok:65535"],
  ["number 80", 80, "ok:80"],
  ["number 3000", 3000, "ok:3000"],
  ["number 65535.0", 65535.0, "ok:65535"],
  ["string '1'", "1", "ok:1"],
  ["string '65535'", "65535", "ok:65535"],
  ["string '80'", "80", "ok:80"],
  ["string '00123'", "00123", "ok:123"],
  ["boolean true", true, "throw"],
  ["boolean false", false, "throw"],
  ["null", null, "throw"],
  ["undefined", undefined, "throw"],
  ["empty string", "", "throw"],
  ["spaces", "   ", "throw"],
  ["tab", "\t", "throw"],
  ["newline", "\n", "throw"],
  ["leading space ' 80'", " 80", "throw"],
  ["trailing space '80 '", "80 ", "throw"],
  ["interior space '8 0'", "8 0", "throw"],
  ["fractional number 1.5", 1.5, "throw"],
  ["fractional number 0.5", 0.5, "throw"],
  ["fractional string '1.5'", "1.5", "throw"],
  ["fractional string '1.0'", "1.0", "throw"],
  ["signed '+1'", "+1", "throw"],
  ["signed '-1'", "-1", "throw"],
  ["exponent '1e3'", "1e3", "throw"],
  ["exponent '1E3'", "1E3", "throw"],
  ["exponent '1e+3'", "1e+3", "throw"],
  ["hex '0x50'", "0x50", "throw"],
  ["NaN", NaN, "throw"],
  ["Infinity", Infinity, "throw"],
  ["-Infinity", -Infinity, "throw"],
  ["number 0", 0, "throw"],
  ["number -1", -1, "throw"],
  ["number 65536", 65536, "throw"],
  ["string '0'", "0", "throw"],
  ["string '65536'", "65536", "throw"],
  ["string overflow '9'.repeat(30)", "9".repeat(30), "throw"],
  ["object {}", {}, "throw"],
  ["array []", [], "throw"],
  ["function", () => {}, "throw"],
  ["bigint 1n", 1n, "throw"],
];

const results = [];
let pass = 0, fail = 0;
for (const [label, value, expected] of cases) {
  let actual;
  let threw = false;
  let errType = null;
  try {
    actual = port(value);
  } catch (e) {
    threw = true;
    errType = e && e.constructor ? e.constructor.name : String(e);
  }
  let observed;
  if (threw) {
    observed = errType === "TypeError" ? "throw" : "throw(" + errType + ")";
  } else {
    observed = "ok:" + actual;
  }
  const ok = observed === expected;
  if (ok) pass++; else fail++;
  results.push({ label, expected, observed, ok });
}

return { pass, fail, total: results.length, results };
